package dev.mineagent.runtime.neoforge.client;
import java.util.*;import java.util.concurrent.*;import java.io.*;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.texture.DynamicTexture;
/** Capture only this AI's currently resolved game skin; no arbitrary local file reads. */
public final class AgentSkinSource {
 public record Image(byte[] png,String model){}
 public static CompletableFuture<Image> capture(UUID agent){var result=new CompletableFuture<Image>();var mc=Minecraft.getInstance();mc.execute(()->{try{if(mc.getConnection()==null)throw new IllegalStateException("SKIN_CLIENT_DISCONNECTED");var skin=AgentSkinClient.skin(agent);if(skin==null){var info=mc.getConnection().getPlayerInfo(agent);if(info==null)throw new IllegalStateException("SKIN_AI_NOT_VISIBLE");skin=info.getSkin();}var path=skin.body().texturePath();var texture=mc.getTextureManager().getTexture(path);byte[] bytes;if(texture instanceof DynamicTexture dynamic&&dynamic.getPixels()!=null){var pixels=dynamic.getPixels();if(pixels.getWidth()!=64||pixels.getHeight()!=64&&pixels.getHeight()!=32)throw new IllegalStateException("SKIN_SIZE_64_REQUIRED");var image=new java.awt.image.BufferedImage(pixels.getWidth(),pixels.getHeight(),java.awt.image.BufferedImage.TYPE_INT_ARGB);image.setRGB(0,0,pixels.getWidth(),pixels.getHeight(),pixels.getPixels(),0,pixels.getWidth());var out=new ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"PNG",out);bytes=out.toByteArray();}else try(var in=mc.getResourceManager().getResourceOrThrow(path).open()){bytes=in.readNBytes(262145);}result.complete(new Image(dev.mineagent.runtime.core.agent.SkinImage.normalize(bytes),skin.model()==net.minecraft.world.entity.player.PlayerModelType.SLIM?"slim":"wide"));}catch(Exception e){result.completeExceptionally(e);}});return result;}
 private AgentSkinSource(){}
}
